import os
os.environ.setdefault('DJANGO_SETTINGS_MODULE', 'settings')

import django
from django.conf import settings
settings.configure(
    DATABASES={'default': {'ENGINE': 'django.db.backends.sqlite3', 'NAME': ':memory:'}},
    INSTALLED_APPS=[
        'django.contrib.contenttypes',
    ]
)
django.setup()

from django.db import models

# Test 1: Basic case - ordering by related field pk
class Option1(models.Model):
    name = models.CharField(max_length=100)

    class Meta:
        app_label = 'test_app1'

class Model1(models.Model):
    option = models.ForeignKey(Option1, on_delete=models.CASCADE)

    class Meta:
        app_label = 'test_app1'
        ordering = ('option__pk',)

print("Test 1: Basic option__pk")
errors = Model1.check()
pk_errors = [e for e in errors if e.id == 'models.E015']
print(f"  E015 errors: {len(pk_errors)} (expected: 0)")
if pk_errors:
    for e in pk_errors:
        print(f"    {e}")

# Test 2: Multi-level relation with pk
class GrandParent(models.Model):
    name = models.CharField(max_length=100)

    class Meta:
        app_label = 'test_app2'

class Parent(models.Model):
    grandparent = models.ForeignKey(GrandParent, on_delete=models.CASCADE)

    class Meta:
        app_label = 'test_app2'

class Model2(models.Model):
    parent = models.ForeignKey(Parent, on_delete=models.CASCADE)

    class Meta:
        app_label = 'test_app2'
        ordering = ('parent__grandparent__pk',)

print("\nTest 2: Multi-level parent__grandparent__pk")
errors = Model2.check()
pk_errors = [e for e in errors if e.id == 'models.E015']
print(f"  E015 errors: {len(pk_errors)} (expected: 0)")
if pk_errors:
    for e in pk_errors:
        print(f"    {e}")

# Test 3: Invalid related field that ends with pk should still error
class Model3(models.Model):
    name = models.CharField(max_length=100)

    class Meta:
        app_label = 'test_app3'
        ordering = ('nonexistent__pk',)

print("\nTest 3: Invalid nonexistent__pk (should error)")
errors = Model3.check()
pk_errors = [e for e in errors if e.id == 'models.E015']
print(f"  E015 errors: {len(pk_errors)} (expected: 1)")
