class Option5(models.Model):
    name = models.CharField(max_length=100)

    class Meta:
        app_label = 'test_app5'

class Model5(models.Model):
    option = models.ForeignKey(Option5, on_delete=models.CASCADE)

    class Meta:
        app_label = 'test_app5'
        ordering = ('option__name',)

print("\nTest 5: Valid option__name")
errors = Model5.check()
pk_errors = [e for e in errors if e.id == 'models.E015']
print(f"  E015 errors: {len(pk_errors)} (expected: 0)")
if pk_errors:
    for e in pk_errors:
        print(f"    {e}")

